"use client";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { PlusIcon, X } from "lucide-react";
import { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";

interface Excursion {
  id: string;
  Titulo_Salida: string;
  Como_Llegar: string;
  Que_Llevar: string[];
  Cuanto_Dura: string;
}

export default function ExcursaUBAPage() {
  const [excursions, setExcursions] = useState<Excursion[]>([]);
  const [newExcursion, setNewExcursion] = useState<Excursion>({
    id: "",
    Titulo_Salida: "",
    Como_Llegar: "",
    Que_Llevar: [],
    Cuanto_Dura: "",
  });
  const [currentItem, setCurrentItem] = useState("");
  const [isDialogOpen, setIsDialogOpen] = useState(false);

  // Carga inicial
  useEffect(() => {
    fetch("http://127.0.0.1:8090/api/collections/Salidas_Alumnos/records?page=1&perPage=30")
      .then((res) => res.json())
      .then((data) => {
        const parsed = data.items.map((item: any) => ({
          id: item.id,
          Titulo_Salida: item.Titulo_Salida,
          Como_Llegar: item.Como_Llegar,
          Que_Llevar: item.Que_Llevar || [],
          Cuanto_Dura: item.Cuanto_Dura,
        }));
        setExcursions(parsed);
      })
      .catch(console.error);
  }, []);

  // Agregar ítem a Que_Llevar
  const handleAddItem = () => {
    if (currentItem.trim()) {
      setNewExcursion({
        ...newExcursion,
        Que_Llevar: [...newExcursion.Que_Llevar, currentItem.trim()],
      });
      setCurrentItem("");
    }
  };

  const handleRemoveItem = (index: number) => {
    setNewExcursion({
      ...newExcursion,
      Que_Llevar: newExcursion.Que_Llevar.filter((_, i) => i !== index),
    });
  };

  const handleAddPropuesta = () => {
    const { Titulo_Salida, Como_Llegar, Cuanto_Dura } = newExcursion;
    if (!Titulo_Salida || !Como_Llegar || !Cuanto_Dura) {
      alert("Por favor completa todos los campos.");
      return;
    }

    fetch("http://127.0.0.1:8090/api/collections/Salidas_Alumnos/records", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(newExcursion),
    })
      .then((res) => res.json())
      .then((data) => {
        setExcursions([...excursions, { ...newExcursion, id: data.id }]);
        setNewExcursion({ id: "", Titulo_Salida: "", Como_Llegar: "", Que_Llevar: [], Cuanto_Dura: "" });
        setCurrentItem("");
        setIsDialogOpen(false);
        alert("Nueva propuesta agregada exitosamente.");
      })
      .catch(console.error);
  };

  const cardColors = [
    "bg-[oklch(0.35_0.12_255)]",
    "bg-[oklch(0.75_0.08_220)]",
    "bg-[oklch(0.65_0.15_210)]",
    "bg-[oklch(0.50_0.10_240)]",
  ];

  return (
    <div className="min-h-screen bg-background p-4 md:p-8">
      <div className="mx-auto max-w-6xl">
        <header className="mb-10 text-center">
          <h1 className="text-5xl font-bold text-[oklch(0.27_0.12_255)]">ExcursaUBA</h1>
        </header>

        {/* Tarjetas */}
        <div className="grid gap-6 md:grid-cols-2">
          {excursions.map((exc, i) => (
            <Card key={exc.id} className={`border-4 border-white shadow-lg ${cardColors[i % cardColors.length]}`}>
              <CardHeader className="border-b-2 border-white/30 bg-white/10">
                <CardTitle className="text-white text-2xl">{exc.Titulo_Salida}</CardTitle>
              </CardHeader>
              <CardContent className="text-white">
                <p><b>Cómo llegar:</b> {exc.Como_Llegar}</p>
                <p className="mt-2"><b>Qué llevar:</b></p>
                <ul className="list-disc list-inside ml-5">
                  {exc.Que_Llevar.map((item, idx) => <li key={idx}>{item}</li>)}
                </ul>
                <p className="mt-2"><b>Duración:</b> {exc.Cuanto_Dura}</p>
              </CardContent>
            </Card>
          ))}
        </div>

        {/* Botón Modal */}
        <div className="mt-8 flex justify-center">
          <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
            <DialogTrigger asChild>
              <Button className="w-full max-w-md bg-[oklch(0.65_0.15_210)] text-white py-4 font-bold flex items-center justify-center gap-2">
                <PlusIcon className="h-6 w-6" /> Agregar Nueva Propuesta
              </Button>
            </DialogTrigger>

            <DialogContent className="sm:max-w-lg">
              <DialogHeader>
                <DialogTitle>Nueva Propuesta</DialogTitle>
              </DialogHeader>

              <div className="flex flex-col gap-4">
                <Input
                  placeholder="Título de la salida"
                  value={newExcursion.Titulo_Salida}
                  onChange={(e) => setNewExcursion({ ...newExcursion, Titulo_Salida: e.target.value })}
                />
                <Input
                  placeholder="Cómo llegar"
                  value={newExcursion.Como_Llegar}
                  onChange={(e) => setNewExcursion({ ...newExcursion, Como_Llegar: e.target.value })}
                />
                <Input
                  placeholder="Duración"
                  value={newExcursion.Cuanto_Dura}
                  onChange={(e) => setNewExcursion({ ...newExcursion, Cuanto_Dura: e.target.value })}
                />
                <div className="flex gap-2">
                  <Input
                    placeholder="Agregar ítem a llevar"
                    value={currentItem}
                    onChange={(e) => setCurrentItem(e.target.value)}
                  />
                  <Button onClick={handleAddItem}>Agregar</Button>
                </div>

                <ul className="list-disc list-inside ml-5">
                  {newExcursion.Que_Llevar.map((item, i) => (
                    <li key={i} className="flex justify-between items-center">
                      {item}
                      <X className="cursor-pointer" onClick={() => handleRemoveItem(i)} />
                    </li>
                  ))}
                </ul>
              </div>

              <DialogFooter>
                <Button onClick={handleAddPropuesta} className="w-full">Guardar Propuesta</Button>
              </DialogFooter>
            </DialogContent>
          </Dialog>
        </div>
      </div>
    </div>
  );
}